import{_ as e,a0 as o,w as s,s as p,I as r,x as i,a1 as l,A as n,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"在 Linux 下用 Krita 进行照片编辑 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下用 Krita 进行照片编辑 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下用 Krita 进行照片编辑 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下用 Krita 进行照片编辑 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140902 Photo Editing on Linux with Krita","title":"在 Linux 下用 Krita 进行照片编辑","tag":"201410","desc":""},"relativePath":"201410/20140902 Photo Editing on Linux with Krita.md","filePath":"[post].md"}'),m={name:"201410/20140902 Photo Editing on Linux with Krita.md"};function d(g,t,x,f,w,K){const a=o("Link");return s(),p("div",null,[t[19]||(t[19]=r("h1",{id:"在-linux-下用-krita-进行照片编辑",tabindex:"-1"},[i("在 Linux 下用 Krita 进行照片编辑 "),r("a",{class:"header-anchor",href:"#在-linux-下用-krita-进行照片编辑","aria-label":"Permalink to “在 Linux 下用 Krita 进行照片编辑”"},"​")],-1)),t[20]||(t[20]=r("img",{src:"http://www.linux.com/images/stories/41373/fig-1-annabelle.jpg"},null,-1)),t[21]||(t[21]=r("small",null,"图 1：侏儒山羊 Annabelle",-1)),r("p",null,[l(a,{href:"https://krita.org/"},{default:n(()=>[...t[0]||(t[0]=[i("Krita",-1)])]),_:1}),t[1]||(t[1]=i(" 是一款很棒的绘图应用，同时也是很不错的照片编辑器。今天我们将学习如何给图片添加文字，以及如何有选择地锐化照片的某一部分。",-1))]),t[22]||(t[22]=u('<h3 id="krita-简介" tabindex="-1">Krita 简介 <a class="header-anchor" href="#krita-简介" aria-label="Permalink to “Krita 简介”">​</a></h3><p>与其他绘图/制图应用类似，Krita 内置了数百种工具和选项，以及多种处理方法。因此它值得我们花点时间来了解一下。</p><p>Krita 默认使用了暗色主题。我不太喜欢暗色主题，但幸运的是 Krita 还有其他很赞的主题，你可以在任何时候通过菜单里的“设置 &gt; 主题”进行更改。</p><p>Krita 使用了窗口停靠样式的工具条。如果左右两侧面板的 Dock 工具条没有显示，检查一下“设置 &gt; 显示工具条”选项，你也可以在“设置 &gt; 工具条”中对工具条按你的偏好进行调整。不过隐藏的工具条也许会让你感到一些小小的不快，它们只会在一个狭小的压扁区域展开，你看不见其中的任何东西。你可以拖动它们至顶端或者 Krita 窗口的一侧，放大或者缩小它们，甚至你可以把它们拖到 Krita 外，放在你显示屏的任意位置。如果你把其中一个工具条拖到了另一个工具条上，它们会自动合并成一个工具条。</p><p>当你配置好比较满意的工作区后，你可以在“选择工作区”内保存它。你可以在笔刷工具条（通过“设置 &gt; 显示工具条”开启显示）的右侧找到“选择工作区”。其中有对工作区的不同配置，当然你也可以创建自己的配置（图 2）。</p><img src="http://www.linux.com/images/stories/41373/fig-2-workspaces.jpg"><small>图 2：在“选择工作区”里保存用户定制的工作区。</small><p>Krita 中有多重缩放控制方法。Ctrl + “=” 放大，Ctrl + “-” 缩小，Ctrl + “0” 重置为 100% 缩放画面。你也可以通过“视图 &gt; 缩放”，或者右下角的缩放条进行控制。在缩放条的左侧还有一个下拉式的缩放菜单。</p><p>工具菜单位于窗口左部，其中包含了锐化和选择工具。你必须移动光标到每个工具上，才能查看它的标签。工具选项条总是显示当前正在使用的工具的选项，默认情况下工具选项条位于窗口右部。</p><h3 id="裁切工具" tabindex="-1">裁切工具 <a class="header-anchor" href="#裁切工具" aria-label="Permalink to “裁切工具”">​</a></h3><p>当然，在工具菜单条中有裁切工具，并且非常易于使用。把你想要选择的区域用矩形圈定，使用拖拽的方式来调整选区，调整完毕后点击返回按钮。在工具选项条中，你可以选择对所有图层应用裁切，还是只对当前图层应用裁切，通过输入具体数值，或者是百分比调整尺寸。</p><h3 id="添加文本" tabindex="-1">添加文本 <a class="header-anchor" href="#添加文本" aria-label="Permalink to “添加文本”">​</a></h3><p>当你想在照片上添加标签或者说明这类简单文本的时候，Krita 也许会让你眼花缭乱，因为它有太多的艺术字效果可供选择了。但 Krita 同时也支持添加简单的文字。点击文本工具条，你将会看到工具选项条如图 3 那样。</p><img src="http://www.linux.com/images/stories/41373/fig-3-text.jpg"><small>图 3：文本选项。</small><p>点击展开按钮。这将显示简单文本工具；首先绘制矩形文本框，接着在文本框内输入文字。工具选项条中有所有常用的文本格式选项：文本选择、文本尺寸、文字与背景颜色、边距，以及一系列图形风格。但你处理完文本后点击外观处理工具，外观处理工具的按钮是一个白色的箭头，在文本工具按钮旁边，通过外观处理工具你可以调整文字整体的尺寸、外观还有位置。外观处理工具的工具选项包括多种不同的线条、颜色还有边距。图 4 是我为我那些蜗居在城市里的亲戚们发送的一幅带有愉快标题的照片。</p><img src="http://www.linux.com/images/stories/41373/fig-4-frontdoor.jpg"><small>图 4：来这绿色农场吧。</small><p>如何处理你的照片上已经存在的文字？点击外观处理工具，在文本区域内双击。这将使文本进入编辑模式，从文本框内出现的光标可以看出这一点。现在，你就可以开始选择文字、添加文字、更改格式，等等。</p><h3 id="锐化选区" tabindex="-1">锐化选区 <a class="header-anchor" href="#锐化选区" aria-label="Permalink to “锐化选区”">​</a></h3><p>外观编辑上，Krita 有许多很棒的工具。在图 5 中我想要锐化 Annabelle 的脸和眼睛。（Annabelle 住在隔壁，但她很喜欢我的狗，在我这里呆了很长一段时间。我的狗却因为害怕她而跑了，但她却一点也不气馁。）首先通过“外形选区”工具选择一个区域。接着打开“滤镜 &gt; 增强 &gt; 虚边蒙板”。你可以调节三个变量：半长值、总量以及阈值。大多数图像编辑软件都有半径、总量和阀值的设置。半径是直径的一半，因此从技术上来说“半长值”是正确的，但却可能造成不必要的混乱。</p><img src="http://www.linux.com/images/stories/41373/fig-5-annabelle.jpg"><small>图 5：选取任意的区域进行编辑。</small><p>半长值决定了锐化线条的粗细。你需要足够大的数值来产生较好的结果，但很明显，不要过大。</p><p>阀值决定了锐化时两个像素点之间的效果差异。“0”是锐化的最大值，“99”则表示不进行锐化。</p><p>总量控制着锐化强度；其值越高锐化程度越高。</p><p>锐化基本上是你处理照片的最后一步，因为它和你对照片所做的一切处理都有关：裁切、改变尺寸、颜色、色差...如果你先进行锐化再进行其他操作，你的锐化效果将变得一团糟。</p><p>接着，你要问，“虚化蒙板”是什么意思？这个名字来源于锐化技术：虚化蒙板滤镜在原始图像上覆盖一层模糊的蒙板，接着在上面分层进行虚化蒙板。这将使图像比直接锐化产生更加锐利清晰的效果。</p>',28)),r("p",null,[t[3]||(t[3]=i("今天要说的就这么多。有关 Krita 的资料很多，但比较杂乱。你可以从 ",-1)),l(a,{href:"https://krita.org/learn/tutorials/"},{default:n(()=>[...t[2]||(t[2]=[i("Krita Tutorials",-1)])]),_:1}),t[4]||(t[4]=i(" 开始学习，也可以在 YouTube 上找寻相关的学习视频。",-1))]),r("ul",null,[r("li",null,[l(a,{href:"https://krita.org/"},{default:n(()=>[...t[5]||(t[5]=[i("krita 官方网站",-1)])]),_:1})])]),t[23]||(t[23]=r("hr",null,null,-1)),r("p",null,[t[7]||(t[7]=i("via: ",-1)),l(a,{href:"http://www.linux.com/learn/tutorials/786040-photo-editing-on-linux-with-krita"},{default:n(()=>[...t[6]||(t[6]=[i("http://www.linux.com/learn/tutorials/786040-photo-editing-on-linux-with-krita",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=i("作者：",-1)),l(a,{href:"http://www.linux.com/community/forums/person/3734"},{default:n(()=>[...t[8]||(t[8]=[i("Carla Schroder",-1)])]),_:1}),t[12]||(t[12]=i(" 译者：",-1)),l(a,{href:"https://github.com/SteveArcher"},{default:n(()=>[...t[9]||(t[9]=[i("SteveArcher",-1)])]),_:1}),t[13]||(t[13]=i(" 校对：",-1)),l(a,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...t[10]||(t[10]=[i("Caroline",-1)])]),_:1})]),r("p",null,[t[16]||(t[16]=i("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[14]||(t[14]=[i("LCTT",-1)])]),_:1}),t[17]||(t[17]=i(" 原创翻译，",-1)),l(a,{href:"http://linux.cn/"},{default:n(()=>[...t[15]||(t[15]=[i("Linux中国",-1)])]),_:1}),t[18]||(t[18]=i(" 荣誉推出",-1))])])}const C=e(m,[["render",d]]);export{k as __pageData,C as default};
